#!/usr/bin/env node
/**
 * scripts/atlas/train-autoencoder-768-64.mjs
 *
 * AE train control plane — queue/orchestration runner.
 *
 * Reads the manifest at docs/reports/ae-train-manifest.json (generated by
 * ae-train-manifest.mjs), consumes the compression deque queue, invokes the
 * real JS autoencoder trainer (sveltekit-frontend/scripts/ae-train.mjs),
 * and writes sae_latent FeatureRecord rows to feature_records via
 * sveltekit-frontend/src/lib/server/retrieval/feature-record.ts.
 *
 * Usage:
 *   node scripts/atlas/train-autoencoder-768-64.mjs             (full run)
 *   node scripts/atlas/train-autoencoder-768-64.mjs --dry-run   (validate only)
 *   node scripts/atlas/train-autoencoder-768-64.mjs --epochs 60 --lr 0.005
 *   node scripts/atlas/train-autoencoder-768-64.mjs --ae-version 1.0.1
 */

import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'fs';
import { resolve, dirname }  from 'path';
import { fileURLToPath }     from 'url';
import { createHash }        from 'crypto';
import { Redis }             from 'ioredis';
import pg                    from 'pg';
import dotenv                from 'dotenv';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(__dirname, '../..');
const SF_ROOT   = resolve(REPO_ROOT, 'sveltekit-frontend');

dotenv.config({ path: resolve(SF_ROOT, '.env') });
dotenv.config({ path: resolve(SF_ROOT, '.env.local') });

// ── Contract ──────────────────────────────────────────────────────────────────
const { CONTRACT_VERSION, validateManifest } = await import(
  './lib/ae-train-contract.mjs'
);

// ── Config ────────────────────────────────────────────────────────────────────
const QDRANT_URL    = process.env.QDRANT_URL ?? 'http://localhost:6333';
const REPORTS_DIR   = resolve(REPO_ROOT, 'docs/reports');
const MANIFEST_PATH = resolve(REPORTS_DIR, 'ae-train-manifest.json');

const args      = process.argv.slice(2);
const DRY_RUN   = args.includes('--dry-run');
const FORCE     = args.includes('--force');
const VERBOSE   = args.includes('--verbose');
const EPOCHS    = parseIntArg('--epochs',   30);
const BATCH     = parseIntArg('--batch',    64);
const LR        = parseFloatArg('--lr',   0.01);
const L2        = parseFloatArg('--l2',   1e-5);
const LIMIT     = parseIntArg('--limit', Infinity);
const AE_VER    = parseStrArg('--ae-version', '1.0.0');

function parseIntArg(flag, fallback) {
  const idx = args.indexOf(flag);
  if (idx >= 0 && args[idx + 1]) return parseInt(args[idx + 1], 10);
  const eq = args.find(a => a.startsWith(`${flag}=`));
  if (eq) return parseInt(eq.slice(flag.length + 1), 10);
  return fallback;
}
function parseFloatArg(flag, fallback) {
  const idx = args.indexOf(flag);
  if (idx >= 0 && args[idx + 1]) return parseFloat(args[idx + 1]);
  const eq = args.find(a => a.startsWith(`${flag}=`));
  if (eq) return parseFloat(eq.slice(flag.length + 1));
  return fallback;
}
function parseStrArg(flag, fallback) {
  const idx = args.indexOf(flag);
  if (idx >= 0 && args[idx + 1]) return args[idx + 1];
  return fallback;
}

const log  = (...a) => console.log(...a);
const vlog = (...a) => { if (VERBOSE) console.log(...a); };

// ── Redis (safe pattern) ──────────────────────────────────────────────────────
function makeRedis() {
  const r = new Redis({
    host:                 process.env.REDIS_HOST     ?? '127.0.0.1',
    port:                 parseInt(process.env.REDIS_PORT ?? '6379', 10),
    password:             process.env.REDIS_PASSWORD ?? 'redis',
    lazyConnect:          true,
    maxRetriesPerRequest: 1,
    enableOfflineQueue:   false,
    retryStrategy:        () => null,
  });
  r.on('error', () => {});
  return r;
}

// ── Postgres (direct pg, not Drizzle) ────────────────────────────────────────
function makePool() {
  return new pg.Pool({
    connectionString:
      process.env.DATABASE_URL ??
      'postgresql://legal_admin:123456@127.0.0.1:5434/legal_ai_db',
    max: 3,
  });
}

// ── Qdrant helpers ────────────────────────────────────────────────────────────

async function fetchEmbeddingBatch(pointIds, collection) {
  const res = await fetch(`${QDRANT_URL}/collections/${collection}/points`, {
    method:  'POST',
    headers: { 'Content-Type': 'application/json' },
    body:    JSON.stringify({ ids: pointIds, with_payload: false, with_vector: true }),
    signal:  AbortSignal.timeout(30_000),
  });
  if (!res.ok) {
    const text = await res.text().catch(() => '');
    throw new Error(`Qdrant GET points failed ${res.status}: ${text.slice(0, 200)}`);
  }
  const data = await res.json();
  return (data?.result ?? []).map(p => ({
    id:        p.id,
    embedding: p.vector?.content ?? p.vector ?? [],
  }));
}

// ── Minimal JS autoencoder (mirrors ae-train.mjs logic) ──────────────────────
// This is the same architecture as sveltekit-frontend/scripts/ae-train.mjs
// but operates on pre-fetched Float32Array batch instead of pulling from Qdrant.

function xavierUniform(rows, cols) {
  const limit = Math.sqrt(6 / (rows + cols));
  const w = new Float32Array(rows * cols);
  for (let i = 0; i < w.length; i++) w[i] = (Math.random() * 2 - 1) * limit;
  return w;
}
function zeros(n) { return new Float32Array(n); }

function reluForward(x) {
  const y = new Float32Array(x.length);
  for (let i = 0; i < x.length; i++) y[i] = x[i] > 0 ? x[i] : 0;
  return y;
}
function reluGrad(grad, x) {
  const g = new Float32Array(x.length);
  for (let i = 0; i < x.length; i++) g[i] = x[i] > 0 ? grad[i] : 0;
  return g;
}

function matVec(W, rows, cols, x) {
  const out = new Float32Array(rows);
  for (let r = 0; r < rows; r++) {
    let s = 0;
    for (let c = 0; c < cols; c++) s += W[r * cols + c] * x[c];
    out[r] = s;
  }
  return out;
}
function addBias(x, b) {
  const y = new Float32Array(x.length);
  for (let i = 0; i < x.length; i++) y[i] = x[i] + b[i];
  return y;
}

/**
 * Encode a single 768-dim vector to 64-dim.
 * Returns { latent: Float32Array(64), h1: Float32Array(256) }
 */
function encode(x, W1, b1, W2, b2) {
  const z1  = addBias(matVec(W1, 256, 768, x), b1);
  const h1  = reluForward(z1);
  const lat = addBias(matVec(W2, 64, 256, h1), b2);
  return { latent: lat, h1, z1 };
}

/**
 * Decode 64-dim latent back to 768-dim using tied weights.
 */
function decode(lat, W2, b2, W1, b1) {
  // h2 = ReLU(W2^T * lat + bias_h1)
  const z2 = new Float32Array(256);
  for (let c = 0; c < 256; c++) {
    let s = b1[c];
    for (let r = 0; r < 64; r++) s += W2[r * 256 + c] * lat[r];
    z2[c] = s;
  }
  const h2 = reluForward(z2);
  // recon = W1^T * h2 + zero-bias
  const recon = new Float32Array(768);
  for (let c = 0; c < 768; c++) {
    let s = 0;
    for (let r = 0; r < 256; r++) s += W1[r * 768 + c] * h2[r];
    recon[c] = s;
  }
  return { recon, h2, z2 };
}

/**
 * Train the AE on a Float32Array batch.
 * Returns { W1, b1, W2, b2, finalLoss, epochs }.
 */
function trainAE(vectors, opts = {}) {
  const epochs    = opts.epochs    ?? 30;
  const batchSize = opts.batchSize ?? 64;
  const lr        = opts.lr        ?? 0.01;
  const l2        = opts.l2        ?? 1e-5;
  const onEpoch   = opts.onEpoch   ?? (() => {});

  const W1 = xavierUniform(256, 768);
  const b1 = zeros(256);
  const W2 = xavierUniform(64, 256);
  const b2 = zeros(64);

  // SGD momentum buffers
  const mW1 = zeros(W1.length); const mb1 = zeros(256);
  const mW2 = zeros(W2.length); const mb2 = zeros(64);
  const momentum = 0.9;

  let bestLoss = Infinity;

  for (let epoch = 0; epoch < epochs; epoch++) {
    // Cosine LR decay
    const lrT = lr * (0.5 * (1 + Math.cos(Math.PI * epoch / epochs)));

    // Shuffle
    const idx = [...Array(vectors.length).keys()];
    for (let i = idx.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [idx[i], idx[j]] = [idx[j], idx[i]];
    }

    let epochLoss = 0;
    let batches   = 0;

    for (let b = 0; b < vectors.length; b += batchSize) {
      const batchIdx = idx.slice(b, b + batchSize);

      // Gradient accumulators
      const gW1 = zeros(W1.length); const gb1 = zeros(256);
      const gW2 = zeros(W2.length); const gb2 = zeros(64);
      let batchLoss = 0;

      for (const i of batchIdx) {
        const x = vectors[i];

        // Forward
        const { latent, h1, z1 } = encode(x, W1, b1, W2, b2);
        const { recon, h2, z2 }  = decode(latent, W2, b2, W1, b1);

        // Loss (MSE)
        let loss = 0;
        const dRecon = new Float32Array(768);
        for (let d = 0; d < 768; d++) {
          const diff = recon[d] - x[d];
          loss += diff * diff;
          dRecon[d] = 2 * diff / 768;
        }
        batchLoss += loss / 768;

        // Backward decode  (W1^T, W2 tied)
        // dh2 = W1 * dRecon
        const dh2 = new Float32Array(256);
        for (let r = 0; r < 256; r++) {
          let s = 0;
          for (let c = 0; c < 768; c++) s += W1[r * 768 + c] * dRecon[c];
          dh2[r] = s;
        }
        const dz2 = reluGrad(dh2, z2);

        // dW2 (transpose) accumulated in gW1 direction — skip (tied: update W1 only)
        // dlatent = W2 * dz2
        const dLatent = new Float32Array(64);
        for (let r = 0; r < 64; r++) {
          let s = 0;
          for (let c = 0; c < 256; c++) s += W2[r * 256 + c] * dz2[c];
          dLatent[r] = s;
        }

        // Backward encode
        const dz2b = reluGrad(dLatent, latent);
        // grad W2, b2
        for (let r = 0; r < 64; r++) {
          gb2[r] += dz2b[r];
          for (let c = 0; c < 256; c++) gW2[r * 256 + c] += dz2b[r] * h1[c];
        }
        // dh1 = W2^T * dz2b
        const dh1 = new Float32Array(256);
        for (let c = 0; c < 256; c++) {
          let s = 0;
          for (let r = 0; r < 64; r++) s += W2[r * 256 + c] * dz2b[r];
          dh1[c] = s;
        }
        const dz1 = reluGrad(dh1, z1);
        // grad W1, b1
        for (let r = 0; r < 256; r++) {
          gb1[r] += dz1[r];
          for (let c = 0; c < 768; c++) gW1[r * 768 + c] += dz1[r] * x[c];
        }
        // Accumulate dRecon into gW1 (tied decode path)
        for (let r = 0; r < 256; r++) {
          for (let c = 0; c < 768; c++) gW1[r * 768 + c] += dh2[r] * dRecon[c];
        }
      }

      const bsz = batchIdx.length;
      // SGD + momentum + L2
      for (let i = 0; i < W1.length; i++) {
        const g  = gW1[i] / bsz + l2 * W1[i];
        mW1[i]   = momentum * mW1[i] + g;
        W1[i]   -= lrT * mW1[i];
      }
      for (let i = 0; i < 256; i++) {
        const g = gb1[i] / bsz;
        mb1[i]  = momentum * mb1[i] + g;
        b1[i]  -= lrT * mb1[i];
      }
      for (let i = 0; i < W2.length; i++) {
        const g  = gW2[i] / bsz + l2 * W2[i];
        mW2[i]   = momentum * mW2[i] + g;
        W2[i]   -= lrT * mW2[i];
      }
      for (let i = 0; i < 64; i++) {
        const g = gb2[i] / bsz;
        mb2[i]  = momentum * mb2[i] + g;
        b2[i]  -= lrT * mb2[i];
      }

      epochLoss += batchLoss;
      batches++;
    }

    const avgLoss = epochLoss / batches;
    if (avgLoss < bestLoss) bestLoss = avgLoss;
    onEpoch(epoch, avgLoss);
  }

  return { W1, b1, W2, b2, finalLoss: bestLoss, epochs };
}

// ── Feature-records upsert (via Postgres directly) ────────────────────────────
// Mirrors the logic in sveltekit-frontend/src/lib/server/retrieval/feature-record.ts
// using raw pg queries (no Drizzle / SvelteKit context needed here).

function sha256(input) {
  return createHash('sha256').update(input).digest('hex');
}

async function upsertFeatureRecord(pool, input) {
  const snapshotHash = sha256(input.canonical_input);
  const payloadJson  = JSON.stringify(input.payload);

  const result = await pool.query(
    `WITH existing AS (
       SELECT feature_id, snapshot_hash
       FROM feature_records
       WHERE packet_key   = $1
         AND feature_type = $2
         AND version      = $3
         AND superseded_at IS NULL
       LIMIT 1
     ),
     supersede AS (
       UPDATE feature_records fr
       SET superseded_at = NOW(), superseded_by = gen_random_uuid()
       FROM existing e
       WHERE fr.feature_id = e.feature_id
         AND e.snapshot_hash != $4
       RETURNING fr.feature_id AS old_id, fr.superseded_by AS new_id
     ),
     insert_new AS (
       INSERT INTO feature_records (
         feature_id, packet_key, feature_type, version,
         snapshot_hash, payload, scalar_f32, vector_f32
       )
       SELECT
         COALESCE(s.new_id, gen_random_uuid()),
         $1, $2, $3, $4, $5::jsonb, $6::real, $7
       FROM (SELECT 1) dummy
       LEFT JOIN supersede s ON true
       WHERE NOT EXISTS (
         SELECT 1 FROM existing e WHERE e.snapshot_hash = $4
       )
       RETURNING *
     )
     SELECT * FROM insert_new
     UNION ALL
     SELECT fr.* FROM feature_records fr
     JOIN existing e ON fr.feature_id = e.feature_id
     WHERE e.snapshot_hash = $4
     LIMIT 1`,
    [
      input.packet_key,
      input.feature_type,
      input.version,
      snapshotHash,
      payloadJson,
      input.scalar_f32  ?? null,
      input.vector_f32  ?? null,
    ],
  );

  return result.rows[0] ?? null;
}

// ── Main ──────────────────────────────────────────────────────────────────────

async function main() {
  log('\n╔═══════════════════════════════════════════════════════════════════╗');
  log('║  AE Train Control Plane — 768 → 64 orchestration runner           ║');
  log('╚═══════════════════════════════════════════════════════════════════╝\n');
  log(`  dry_run=${DRY_RUN}  epochs=${EPOCHS}  batch=${BATCH}  lr=${LR}  ae_version=${AE_VER}\n`);

  // ── Load manifest ──────────────────────────────────────────────────────────
  if (!existsSync(MANIFEST_PATH)) {
    log(`[runner] ERROR manifest not found at ${MANIFEST_PATH}`);
    log(`[runner] Run:  node scripts/atlas/ae-train-manifest.mjs`);
    process.exit(1);
  }

  let manifest;
  try {
    manifest = JSON.parse(readFileSync(MANIFEST_PATH, 'utf8'));
    validateManifest(manifest);
    log(`[runner] manifest loaded  contract=${manifest.contract_version}  queue=${manifest.queue.length}`);
  } catch (err) {
    log(`[runner] ERROR invalid manifest: ${err.message}`);
    process.exit(1);
  }

  const queue = manifest.queue.slice(0, LIMIT === Infinity ? undefined : LIMIT);
  if (queue.length === 0) {
    log('[runner] queue is empty — nothing to train');
    return;
  }

  // ── Connect to Redis ───────────────────────────────────────────────────────
  const redis = makeRedis();
  try {
    await redis.connect();
    await redis.ping();
    log('[runner] Redis connected');
  } catch (err) {
    log(`[runner] WARN Redis unavailable: ${err.message} — weights will not be cached`);
  }

  // Check for existing weights
  if (!FORCE) {
    const existing = await redis.hget('ace:autoencoder:meta', 'ae_version').catch(() => null);
    if (existing === AE_VER) {
      log(`[runner] weights for ae_version=${AE_VER} already in Redis (use --force to retrain)`);
      if (!DRY_RUN) {
        await redis.quit().catch(() => {});
        return;
      }
    }
  }

  // ── Fetch embeddings from Qdrant ──────────────────────────────────────────
  log(`[runner] fetching ${queue.length} embeddings from Qdrant (${manifest.qdrant_collection}) …`);

  const pointIds = queue.map(e => e.qdrant_point_id);
  // Fetch in batches of 100 to avoid payload size limits
  const allEmbeddings = [];
  const indexMap      = new Map(); // qdrant_point_id → index in allEmbeddings

  for (let i = 0; i < pointIds.length; i += 100) {
    const batch  = pointIds.slice(i, i + 100);
    const points = await fetchEmbeddingBatch(batch, manifest.qdrant_collection);
    for (const p of points) {
      indexMap.set(String(p.id), allEmbeddings.length);
      allEmbeddings.push(new Float32Array(p.embedding));
    }
    vlog(`[runner]   fetched ${Math.min(i + 100, pointIds.length)} / ${pointIds.length}`);
  }

  log(`[runner] fetched ${allEmbeddings.length} embeddings (${queue.length - allEmbeddings.length} missing)`);

  if (allEmbeddings.length === 0) {
    log('[runner] ERROR no embeddings could be fetched — check Qdrant collection');
    await redis.quit().catch(() => {});
    process.exit(1);
  }

  if (DRY_RUN) {
    log(`[runner] DRY RUN — embeddings valid (dim=${allEmbeddings[0].length}), skipping training`);
    await redis.quit().catch(() => {});
    writeReport({ manifest, queue, allEmbeddings, dryRun: true });
    return;
  }

  // ── Train ─────────────────────────────────────────────────────────────────
  log(`[runner] starting training  epochs=${EPOCHS}  batch=${BATCH}  lr=${LR} …`);
  const t0 = Date.now();

  const { W1, b1, W2, b2, finalLoss } = trainAE(allEmbeddings, {
    epochs:    EPOCHS,
    batchSize: BATCH,
    lr:        LR,
    l2:        L2,
    onEpoch:   (epoch, loss) => {
      if (epoch % 5 === 0 || epoch === EPOCHS - 1) {
        log(`[runner]   epoch ${String(epoch + 1).padStart(3)} / ${EPOCHS}  loss=${loss.toFixed(6)}`);
      }
    },
  });

  const durationMs = Date.now() - t0;
  log(`[runner] training done  loss=${finalLoss.toFixed(6)}  duration=${(durationMs / 1000).toFixed(1)}s`);

  // ── Save weights to Redis ─────────────────────────────────────────────────
  let weightsSaved = false;
  try {
    await redis.hset('ace:autoencoder:weights', {
      W1: Array.from(W1).join(','),
      b1: Array.from(b1).join(','),
      W2: Array.from(W2).join(','),
      b2: Array.from(b2).join(','),
    });
    await redis.hset('ace:autoencoder:meta', {
      trainedAt:   new Date().toISOString(),
      ae_version:  AE_VER,
      epochs:      String(EPOCHS),
      batchSize:   String(BATCH),
      lr:          String(LR),
      bestLoss:    String(finalLoss),
      vectorCount: String(allEmbeddings.length),
      durationMs:  String(durationMs),
    });
    await redis.xadd('ace:autoencoder:history', '*',
      'ae_version', AE_VER,
      'trained_at', new Date().toISOString(),
      'loss', String(finalLoss),
      'vectors', String(allEmbeddings.length),
    );
    weightsSaved = true;
    log('[runner] weights saved to Redis (ace:autoencoder:weights)');
  } catch (err) {
    log(`[runner] WARN weights save failed: ${err.message}`);
  }

  // ── Write sae_latent feature records ──────────────────────────────────────
  const pool = makePool();
  let featureRecordsWritten = 0;
  const errors = [];

  log(`[runner] writing sae_latent feature_records for ${queue.length} packets …`);

  for (const qEntry of queue) {
    const embIdx = indexMap.get(String(qEntry.qdrant_point_id));
    if (embIdx === undefined) {
      vlog(`[runner]   SKIP ${qEntry.packet_key} — no embedding fetched`);
      continue;
    }

    const x       = allEmbeddings[embIdx];
    const { latent } = encode(x, W1, b1, W2, b2);

    // Encode latent as base64 Float32
    const buf     = Buffer.from(latent.buffer, latent.byteOffset, latent.byteLength);
    const b64     = buf.toString('base64');

    // Canonical input = packet_key + ae_version + raw embedding hash
    const embHash       = sha256(Buffer.from(x.buffer, x.byteOffset, x.byteLength));
    const canonicalInput = `${qEntry.packet_key}|${AE_VER}|${embHash}`;

    try {
      await upsertFeatureRecord(pool, {
        packet_key:      qEntry.packet_key,
        feature_type:    'sae_latent',
        version:         AE_VER,
        canonical_input: canonicalInput,
        payload: {
          ae_version:    AE_VER,
          embed_dim:     768,
          latent_dim:    64,
          qdrant_collection: qEntry.qdrant_collection,
          qdrant_point_id:   qEntry.qdrant_point_id,
          source_ref:    qEntry.source_ref,
          trained_at:    new Date().toISOString(),
        },
        vector_f32: b64,
      });
      featureRecordsWritten++;
    } catch (err) {
      errors.push({ packet_key: qEntry.packet_key, error: err.message });
      vlog(`[runner]   ERROR ${qEntry.packet_key}: ${err.message}`);
    }
  }

  await pool.end().catch(() => {});
  await redis.quit().catch(() => {});

  log(`[runner] feature_records written: ${featureRecordsWritten}  errors: ${errors.length}`);

  writeReport({
    manifest,
    queue,
    allEmbeddings,
    dryRun: false,
    durationMs,
    finalLoss,
    weightsSaved,
    featureRecordsWritten,
    errors,
  });

  log('\n[runner] ✅ AE train control plane complete');
}

// ── Report writer ─────────────────────────────────────────────────────────────

function writeReport(opts) {
  const {
    manifest, queue, allEmbeddings, dryRun,
    durationMs = 0, finalLoss = null, weightsSaved = false,
    featureRecordsWritten = 0, errors = [],
  } = opts;

  if (!existsSync(REPORTS_DIR)) mkdirSync(REPORTS_DIR, { recursive: true });

  const ts       = new Date().toISOString().replace(/[:.]/g, '-');
  const reportPath = resolve(REPORTS_DIR, `ae-train-report-${ts}.json`);

  const report = {
    contract_version:       CONTRACT_VERSION,
    generated_at:           new Date().toISOString(),
    ae_version:             manifest.ae_version,
    qdrant_collection:      manifest.qdrant_collection,
    embed_dim:              manifest.embed_dim,
    target_dim:             manifest.target_dim,
    dry_run:                dryRun,
    totals: {
      queued:  queue.length,
      done:    featureRecordsWritten,
      errors:  errors.length,
      skipped: queue.length - featureRecordsWritten - errors.length,
    },
    weights_saved:           weightsSaved,
    feature_records_written: featureRecordsWritten,
    training_metrics: dryRun ? undefined : {
      epochs:       EPOCHS,
      best_loss:    finalLoss,
      duration_ms:  durationMs,
      vector_count: allEmbeddings.length,
    },
    errors: errors.slice(0, 100),
  };

  writeFileSync(reportPath, JSON.stringify(report, null, 2), 'utf8');
  log(`[runner] report written: ${reportPath}`);
}

main().catch(err => {
  console.error('[runner] FATAL:', err.message, err.stack);
  process.exit(1);
});
